BEGIN;
CREATE TABLE nova_users (id text PRIMARY KEY, name text NOT NULL, email text UNIQUE NOT NULL, email_verified boolean NOT NULL DEFAULT false, image text, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE nova_sessions (id text PRIMARY KEY, expires_at timestamp NOT NULL, token text UNIQUE NOT NULL, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now(), ip_address text, user_agent text, user_id text NOT NULL REFERENCES nova_users(id) ON DELETE CASCADE);
CREATE INDEX nova_sessions_user_idx ON nova_sessions(user_id);
CREATE TABLE nova_accounts (id text PRIMARY KEY, account_id text NOT NULL, provider_id text NOT NULL, user_id text NOT NULL REFERENCES nova_users(id) ON DELETE CASCADE, access_token text, refresh_token text, id_token text, access_token_expires_at timestamp, refresh_token_expires_at timestamp, scope text, password text, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE INDEX nova_accounts_user_idx ON nova_accounts(user_id);
CREATE TABLE nova_verifications (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, expires_at timestamp NOT NULL, created_at timestamp, updated_at timestamp);
CREATE TABLE nova_workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id text UNIQUE NOT NULL REFERENCES nova_users(id) ON DELETE CASCADE, name text NOT NULL DEFAULT 'Personal workspace');
CREATE TABLE nova_memberships (workspace_id uuid NOT NULL REFERENCES nova_workspaces(id) ON DELETE CASCADE, user_id text NOT NULL REFERENCES nova_users(id) ON DELETE CASCADE, role text NOT NULL CHECK(role='owner'), PRIMARY KEY(workspace_id,user_id));
CREATE TABLE nova_preferences (owner_id text PRIMARY KEY REFERENCES nova_users(id) ON DELETE CASCADE, reduced_motion boolean NOT NULL DEFAULT false, appearance text NOT NULL DEFAULT 'slate' CHECK(appearance IN ('slate','soft')), default_visibility text NOT NULL DEFAULT 'private' CHECK(default_visibility='private'));
CREATE TABLE nova_projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id text NOT NULL REFERENCES nova_users(id) ON DELETE CASCADE, workspace_id uuid NOT NULL REFERENCES nova_workspaces(id) ON DELETE CASCADE, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 80), type text NOT NULL CHECK(type IN ('website','webapp','pwa')), prompt text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','building','ready','published','failed')), current_version_id uuid, archived boolean NOT NULL DEFAULT false, visibility text NOT NULL DEFAULT 'private' CHECK(visibility IN ('private','public')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX nova_projects_owner_updated_idx ON nova_projects(owner_id,updated_at DESC);
CREATE TABLE nova_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES nova_projects(id) ON DELETE CASCADE, owner_id text NOT NULL REFERENCES nova_users(id) ON DELETE CASCADE, files jsonb NOT NULL CHECK(jsonb_typeof(files)='object'), summary text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE nova_projects ADD CONSTRAINT nova_current_version_fk FOREIGN KEY(current_version_id) REFERENCES nova_versions(id) ON DELETE SET NULL;
CREATE INDEX nova_versions_project_idx ON nova_versions(project_id,created_at DESC);
CREATE TABLE nova_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES nova_projects(id) ON DELETE CASCADE, owner_id text NOT NULL REFERENCES nova_users(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('user','assistant')), content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX nova_messages_project_idx ON nova_messages(project_id,created_at);
CREATE TABLE nova_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id text NOT NULL REFERENCES nova_users(id) ON DELETE CASCADE, project_id uuid NOT NULL REFERENCES nova_projects(id) ON DELETE CASCADE, request_key uuid NOT NULL, prompt text NOT NULL CHECK(length(prompt) BETWEEN 3 AND 6000), state text NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','building','ready','failed','cancelled')), phase text NOT NULL DEFAULT 'queued', checkpoint jsonb, attempts integer NOT NULL DEFAULT 0, lease_until timestamptz, error text, sandbox_name text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id,request_key));
CREATE UNIQUE INDEX nova_one_active_job_idx ON nova_jobs(project_id) WHERE state IN ('queued','building');
CREATE INDEX nova_jobs_owner_idx ON nova_jobs(owner_id,created_at DESC);
CREATE TABLE nova_events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, job_id uuid NOT NULL REFERENCES nova_jobs(id) ON DELETE CASCADE, owner_id text NOT NULL REFERENCES nova_users(id) ON DELETE CASCADE, phase text NOT NULL, message text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX nova_events_job_idx ON nova_events(job_id,id);
CREATE TABLE nova_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id text NOT NULL REFERENCES nova_users(id) ON DELETE CASCADE, project_id uuid NOT NULL REFERENCES nova_projects(id) ON DELETE CASCADE, name text NOT NULL, media_type text NOT NULL CHECK(media_type IN ('image/png','image/jpeg','image/webp')), data text NOT NULL CHECK(length(data)<=2800000), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE nova_publications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id text NOT NULL REFERENCES nova_users(id) ON DELETE CASCADE, project_id uuid UNIQUE NOT NULL REFERENCES nova_projects(id) ON DELETE CASCADE, version_id uuid NOT NULL REFERENCES nova_versions(id) ON DELETE CASCADE, slug uuid UNIQUE NOT NULL DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE nova_usage (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, owner_id text NOT NULL REFERENCES nova_users(id) ON DELETE CASCADE, job_id uuid NOT NULL REFERENCES nova_jobs(id) ON DELETE CASCADE, kind text NOT NULL, units integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX nova_usage_owner_idx ON nova_usage(owner_id,created_at DESC);
CREATE TABLE nova_limits (key text PRIMARY KEY, count integer NOT NULL, resets_at timestamptz NOT NULL);
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['nova_workspaces','nova_preferences','nova_projects','nova_versions','nova_messages','nova_jobs','nova_events','nova_assets','nova_publications','nova_usage'] LOOP
  EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('CREATE POLICY owned ON %I TO nova_runtime USING (owner_id = nullif(current_setting(''nova.user_id'',true),'''')) WITH CHECK (owner_id = nullif(current_setting(''nova.user_id'',true),''''))',t);
 END LOOP;
END $$;
ALTER TABLE nova_memberships ENABLE ROW LEVEL SECURITY;
CREATE POLICY owned ON nova_memberships TO nova_runtime USING (user_id = nullif(current_setting('nova.user_id',true),'')) WITH CHECK(user_id = nullif(current_setting('nova.user_id',true),''));
CREATE POLICY publication_read ON nova_publications FOR SELECT TO nova_runtime USING (slug::text=nullif(current_setting('nova.public_slug',true),''));
CREATE POLICY publication_version_read ON nova_versions FOR SELECT TO nova_runtime USING (id IN (SELECT version_id FROM nova_publications WHERE slug::text=nullif(current_setting('nova.public_slug',true),'')));
GRANT USAGE ON SCHEMA public TO nova_runtime;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO nova_runtime;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO nova_runtime;
REVOKE UPDATE,DELETE ON nova_versions FROM nova_runtime;
COMMIT;
